    - `since` (string, optional): Filter results for posts after the indicated datetime (inclusive). Expected to use 'sortAt' timestamp, which may not match 'createdAt'. Can be a datetime, or just an ISO date (YYYY-MM-DD).
    - `sort` (string, optional): Specifies the ranking order of results.
    - `tag` (array, optional): Filter to posts with the given tag (hashtag), based on rich-text facet or tag field. Do not include the hash (#) prefix. Multiple tags can be specified, with 'AND' matching.
    - `until` (string, optional): Filter results for posts before the indicated datetime (not inclusive). Expected to use 'sortAt' timestamp, which may not match 'createdAt'. Can be a datetime, or just an ISO date (YYY-MM-DD).
    - `url` (string, optional): Filter to posts with links (facet links or embeds) pointing to this URL. Server may apply URL normalization or fuzzy matching.

  """
  @spec search_posts(Client.t(), map() | keyword()) :: {:ok, map()} | {:error, term()}
  def search_posts(client, params \\ []) do
    with {:ok, validated} <- validate_search_posts(params) do
      client
      |> Client.query(
        "app.bsky.feed.searchPosts",
        Runtime.encode_query_params(validated, @fields_search_posts)
      )
    end
  end

  defp validate_search_posts(params) do
    {attrs, _extra} = Runtime.atomize(params, @fields_search_posts)

    {f_author, e1} = Runtime.get_string(attrs, :author, "author", format: "at-identifier")
    {f_cursor, e2} = Runtime.get_string(attrs, :cursor, "cursor", [])
    {f_domain, e3} = Runtime.get_string(attrs, :domain, "domain", [])
    {f_lang, e4} = Runtime.get_string(attrs, :lang, "lang", format: "language")

    {f_limit, e5} =
      Runtime.get_integer(attrs, :limit, "limit", minimum: 1, maximum: 100, default: 25)

    {f_mentions, e6} = Runtime.get_string(attrs, :mentions, "mentions", format: "at-identifier")
    {f_q, e7} = Runtime.get_string(attrs, :q, "q", required: true)
    {f_since, e8} = Runtime.get_string(attrs, :since, "since", [])
    {f_sort, e9} = Runtime.get_string(attrs, :sort, "sort", default: "latest")

    {f_tag, e10} =
      Runtime.get_array(attrs, :tag, "tag", [], fn v, path ->
        Runtime.item_string(v, path, max_length: 640, max_graphemes: 64)
      end)

    {f_until, e11} = Runtime.get_string(attrs, :until, "until", [])
    {f_url, e12} = Runtime.get_string(attrs, :url, "url", format: "uri")

    errors = e1 ++ e2 ++ e3 ++ e4 ++ e5 ++ e6 ++ e7 ++ e8 ++ e9 ++ e10 ++ e11 ++ e12

    if errors == [] do
      {:ok,
       %{
         author: f_author,
         cursor: f_cursor,
         domain: f_domain,
         lang: f_lang,
         limit: f_limit,
         mentions: f_mentions,
         q: f_q,
         since: f_since,
         sort: f_sort,
         tag: f_tag,
         until: f_until,
         url: f_url
       }}
    else
      {:error, errors}
    end
  end

  @fields_search_posts_v2 %{
