      end)

    {f_exclude_mentions, e11} =
      Runtime.get_array(attrs, :exclude_mentions, "excludeMentions", [], fn v, path ->
        Runtime.item_string(v, path, format: "at-identifier")
      end)

    {f_exclude_replies, e12} = Runtime.get_boolean(attrs, :exclude_replies, "excludeReplies", [])

    {f_exclude_urls, e13} =
      Runtime.get_array(attrs, :exclude_urls, "excludeUrls", [], fn v, path ->
        Runtime.item_string(v, path, format: "uri")
      end)

    {f_following, e14} = Runtime.get_boolean(attrs, :following, "following", [])
    {f_has_media, e15} = Runtime.get_boolean(attrs, :has_media, "hasMedia", [])
    {f_has_video, e16} = Runtime.get_boolean(attrs, :has_video, "hasVideo", [])

    {f_hashtags, e17} =
      Runtime.get_array(attrs, :hashtags, "hashtags", [], fn v, path ->
