      end)

    {f_languages, e18} =
      Runtime.get_array(attrs, :languages, "languages", [], fn v, path ->
        Runtime.item_string(v, path, format: "language")
      end)

    {f_limit, e19} =
      Runtime.get_integer(attrs, :limit, "limit", minimum: 1, maximum: 100, default: 25)

    {f_mentions, e20} =
      Runtime.get_array(attrs, :mentions, "mentions", [], fn v, path ->
        Runtime.item_string(v, path, format: "at-identifier")
      end)

    {f_query, e21} = Runtime.get_string(attrs, :query, "query", [])
    {f_query_language, e22} = Runtime.get_string(attrs, :query_language, "queryLanguage", [])
    {f_replies_only, e23} = Runtime.get_boolean(attrs, :replies_only, "repliesOnly", [])

    {f_reply_parent_uri, e24} =
      Runtime.get_string(attrs, :reply_parent_uri, "replyParentUri", format: "at-uri")

    {f_since, e25} = Runtime.get_string(attrs, :since, "since", [])
    {f_sort, e26} = Runtime.get_string(attrs, :sort, "sort", [])

    {f_thread_root_uri, e27} =
      Runtime.get_string(attrs, :thread_root_uri, "threadRootUri", format: "at-uri")

    {f_until, e28} = Runtime.get_string(attrs, :until, "until", [])

    {f_urls, e29} =
